import{_ as a,o as s,c as e,ae as t}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"第一版商业 SaaS 数据库，从一家公司的真实需求开始","description":"","frontmatter":{},"headers":[],"relativePath":"posts/first-saas-database-from-real-business-needs.md","filePath":"posts/first-saas-database-from-real-business-needs.md"}'),r={name:"posts/first-saas-database-from-real-business-needs.md"};function o(i,p,l,n,c,d){return s(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="第一版商业-saas-数据库-从一家公司的真实需求开始" tabindex="-1">第一版商业 SaaS 数据库，从一家公司的真实需求开始 <a class="header-anchor" href="#第一版商业-saas-数据库-从一家公司的真实需求开始" aria-label="Permalink to &quot;第一版商业 SaaS 数据库，从一家公司的真实需求开始&quot;">​</a></h1><p>职业转型期间，有一次和朋友聊天，他提到他们公司一直在用一套 SaaS，按年付费。</p><p>我当时认真说了一句：</p><blockquote><p>“如果你们每年订阅那个系统的话，我想试着做一个。”</p></blockquote><p>最开始想得其实很简单。</p><p>就是照着他们正在使用的系统，做一套功能和使用场景差不多的 SaaS。那时候没有认真想过产品定位，也没有考虑过行业竞争。</p><p>甚至能找到多少客户来用，我都不太在意。</p><p>我的想法只是：既然朋友公司本身就在持续付费使用这样一套系统，而且有真实的业务需求，那我可以先做一套替代现有软件的系统，给他们公司使用。</p><p>于是我先去看了他们正在使用的软件，大概了解它有哪些功能、解决哪些问题。</p><p>再后来，我直接去了朋友公司。</p><p>和真正使用系统的人聊他们每天怎么工作，业务怎么流转，哪些事情在系统里完成，哪些环节还需要靠聊天工具或者人工处理。</p><p>那次聊完以后，我觉得业务已经理解得差不多了。</p><p>于是回来开始设计第一版数据库。</p><p>当时觉得整个模型已经比较清楚了。</p><p>然后，真正的问题是在写 API 的时候才出现。</p><h2 id="我决定把第一版推倒重来" tabindex="-1">我决定把第一版推倒重来 <a class="header-anchor" href="#我决定把第一版推倒重来" aria-label="Permalink to &quot;我决定把第一版推倒重来&quot;">​</a></h2><p>根本的问题是：</p><p><strong>我对这个行业的理解，主要来自一家公司，以及他们正在使用的一套软件。</strong></p><p>如果目标只是给朋友公司做一套内部替代系统，这可能已经够了。</p><p>但如果真的准备把它做成商业 SaaS，就不够。</p><p>一家公司的工作方式不代表整个行业，一套现有软件的产品设计也不一定就是最合适的答案。</p><p>所以我没有继续在第一版数据库上修修补补，而是停下来重新研究产品。</p><p>技术上当然可以继续改表、补字段、调整关系，但如果底层的产品假设已经不成立，继续优化只会让自己在错误方向上投入更多。</p><p>这一次，我开始研究行业里已经发展多年的成熟产品，也开始看一些边界相近、但来自其他领域的软件。</p><p>我更关心的是：</p><ul><li>它们为什么这样划分业务对象；</li><li>哪些能力是行业长期沉淀下来的共性；</li><li>哪些设计只是历史包袱；</li><li>不同类型的软件，是怎么解决类似协作问题的；</li><li>哪些环节成熟系统仍然没有解决好。</li></ul><p>遇到新的使用场景，再拿回去找行业里的朋友确认。</p><p>这个过程做下来以后，真正被重做的其实不只是数据库。</p><p><strong>产品定位也重新做了一遍。</strong></p><p>我开始认真考虑：如果这个产品以后真的要卖给更多企业，它和已经存在多年的成熟软件相比，为什么值得被选择？</p><p>我很清楚，如果直接和已经发展多年的成熟软件正面竞争，无论产品完整度、客户积累还是团队资源，都没有优势。</p><p>所以我没有选择去做一个“小号的成熟软件”，而是把范围继续收窄，先找一个足够垂直的小切口。</p><p>与其在主战场正面竞争，不如先找到一个自己能够站住的小山头。</p><p>有限的开发资源，优先集中在几个差异足够明显、真正值得解决的场景上。</p><p>产品边界重新确定以后，我也重新评估了数据库选型。</p><h2 id="数据库也重新选了一次" tabindex="-1">数据库也重新选了一次 <a class="header-anchor" href="#数据库也重新选了一次" aria-label="Permalink to &quot;数据库也重新选了一次&quot;">​</a></h2><p>产品重新定位后，我确定未来会需要地理位置能力，也希望为 AI 检索、RAG 和语义搜索预留空间。</p><p>而作为独立开发者，我的精力是有限的。每多引入一套基础设施，就意味着多一套部署、监控、备份、升级和故障处理。</p><p>这时候我重新看了 PostgreSQL。</p><p>它可以继续承担核心关系型数据，通过 PostGIS 处理地理空间数据，通过 pgvector 支撑前期的向量存储和检索，同时自身也具备全文搜索能力。</p><p>这意味着在产品早期，我暂时不需要同时维护关系数据库、专业向量数据库和 Elasticsearch。</p><p>一套 PostgreSQL，就可以先覆盖当前大部分数据场景。</p><blockquote><p>对独立开发来说，好的技术选型不是把未来所有基础设施提前准备好，而是用尽可能少的组件覆盖当前已经确认的需求，同时不给未来的拆分制造障碍。</p></blockquote><p>第一版真正应该控制的，不只是开发成本。</p><p>还有未来几年自己需要承担的系统复杂度。</p><p>如果未来全文搜索真的复杂到需要 Elasticsearch，或者向量检索超过 pgvector 适合承担的范围，再独立拆出去。现在没有必要提前为还没出现的问题支付复杂度成本。</p><p>回头看，第一版数据库真正需要推倒重来的原因，并不是 MySQL 不合适，也不是某几张表设计得不好。</p><p>表设计不好，可以改；字段不合理，可以调整；关系没拆清楚，也可以继续重构。</p><p>但如果产品定位变了，原来的数据模型即使继续修补，也只是建立在旧的产品假设上。</p><p><strong>真正发生变化的，是产品形态和业务场景本身。</strong></p>',50)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
